import test from 'node:test';import assert from 'node:assert/strict';import{readFileSync}from'node:fs';test('app discloses unfinished AI functionality',()=>{const s=readFileSync('src/main.tsx','utf8');assert.match(s,/chưa khả dụng/)});test('recording is explicitly marked experimental',()=>{const s=readFileSync('src/main.tsx','utf8');assert.match(s,/Không bảo đảm ghi liên tục/);assert.match(s,/đồng ý/)});test('privacy exclusions exist',()=>{const s=readFileSync('.gitignore','utf8');assert.match(s,/recordings\//);assert.match(s,/\.env/)});
